def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def fact(n):
    if n <= 1: return 1
    return n * fact(n - 1)

def factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative integers")
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

